-- Ghi ket luan ban quyen Windows / Office cua bao cao BPVN_BaoCao_BanQuyen_Office_Windows_280926.xlsx (sheet "Chi tiet")
-- vao KK_ThietBi de tab Thiet bi cua /BaoCaoDinhKy ra dung so nhu file.
--   win_license    = cot "Windows - ket luan" (Đạt - MAK công ty / Đạt - OEM Pro theo máy / Gốc Home - mua key nâng cấp Pro /
--                    Cần mua key Windows Pro / Không cần (Linux|macOS)) — BaoCaoDinhKyService.NhomWindows nhan dung cac nhan nay,
--                    dong bo agent khong ghi de nhan da xac minh (ITFormController.DongBoMayTinh).
--   office_license = cot "Key Office": Có key -> 'Có bản quyền', Chưa có key -> 'Chưa có bản quyền' (Notification tinh la co key).
--   can_cai_office = cot "Cần cài Office": Cần Office -> 1, Không cần Office -> 0.
-- Pham vi: May tinh/Laptop cong ty BPVN chua xoa mem, khop ten may voi file: 973 dong.
-- Khong dung toi: 10 may BPVN chua co hostname (file ghi "No Hostname", da tu roi dung nhom: Cần mua key Windows Pro / chua co key Office)
-- va 5 may them sau 28/09 (VN-WT001, VN-WK072, VN-LTB066/067/068) -> trang lech file dung 5 may nay.
-- An toan: chi cap nhat dong con giu dung 3 gia tri cu lay tu DB luc soan (12/10/2026) -> dong ai do vua sua se duoc bo qua,
-- chay lai lan hai cap nhat 0 dong. Rollback: kk-ban-quyen-280926-20261012-rollback.sql
-- Chay bang sqlcmd phai them -f 65001 (file co tieng Viet). Mac dinh ROLLBACK — doi soat xong moi doi sang COMMIT.

SET NOCOUNT ON;
SET XACT_ABORT ON;
BEGIN TRAN;

DECLARE @doi TABLE (id_thiet_bi INT PRIMARY KEY,
    win_cu NVARCHAR(255) NOT NULL, office_cu NVARCHAR(255) NOT NULL, can_cu NVARCHAR(5) NOT NULL,
    win_moi NVARCHAR(255) NOT NULL, office_moi NVARCHAR(255) NOT NULL, can_moi BIT NOT NULL);

-- Doi soat TRUOC
SELECT ISNULL(tb.win_license, N'<trống>') AS Windows, COUNT(*) AS SoMay
FROM KK_ThietBi tb JOIN @doi d ON d.id_thiet_bi = tb.id_thiet_bi GROUP BY tb.win_license ORDER BY SoMay DESC;

UPDATE tb SET tb.win_license = d.win_moi, tb.office_license = d.office_moi, tb.can_cai_office = d.can_moi, tb.ngay_cap_nhat = GETDATE()
FROM KK_ThietBi tb JOIN @doi d ON d.id_thiet_bi = tb.id_thiet_bi
WHERE tb.NgayXoa IS NULL
  AND ISNULL(tb.win_license, N'') = d.win_cu
  AND ISNULL(tb.office_license, N'') = d.office_cu
  AND ISNULL(CAST(tb.can_cai_office AS NVARCHAR(5)), N'') = d.can_cu;
DECLARE @so INT = @@ROWCOUNT;
PRINT N'Đã cập nhật ' + CAST(@so AS NVARCHAR(10)) + N' / 973 dòng';

-- Doi soat SAU: ky vong Đạt - MAK công ty 343; Cần mua key Windows Pro 273; Gốc Home - mua key nâng cấp Pro 266; Đạt - OEM Pro theo máy 88; Không cần (Linux) 2; Không cần (macOS) 1 | Office: can=1 Có bản quyền 236; can=1 Chưa có bản quyền 513; can=0 Có bản quyền 43; can=0 Chưa có bản quyền 181
SELECT tb.win_license AS Windows, COUNT(*) AS SoMay
FROM KK_ThietBi tb JOIN @doi d ON d.id_thiet_bi = tb.id_thiet_bi GROUP BY tb.win_license ORDER BY SoMay DESC;
SELECT tb.can_cai_office AS CanOffice, tb.office_license AS KeyOffice, COUNT(*) AS SoMay
FROM KK_ThietBi tb JOIN @doi d ON d.id_thiet_bi = tb.id_thiet_bi GROUP BY tb.can_cai_office, tb.office_license ORDER BY 1 DESC, 2;

ROLLBACK;
-- COMMIT;
